// Writes src/coffee/words.rs: the words that the big alternations of the
// `coffee` grammar spell out, expanded and sorted.
// A matcher then tests a whole word against a list with a binary search.
//
// `keyword.control` loses its `(?<=for)\s+own` branch, which a matcher tests apart.
// The DOM's `support.function` loses its `plugins.refresh` branch, whose `.` takes any character.
//
// Run with `bun run oracle/coffee-words.ts` and commit the result.
// The output is generated; do not edit it.
import coffee from "@shikijs/langs@4.6.0/coffee";

import { expand } from "./alternation.ts";
import { writeRust } from "./rule-grammar.ts";
import { dedent } from "./dedent.ts";

type Node = { name?: string; match?: string; patterns?: Node[] };
const grammar = (coffee as unknown as { scopeName: string; repository: Record<string, Node>; patterns: Node[] }[]).find(
  (lang) => lang.scopeName === "source.coffee",
)!;

/** The match of the pattern named `name` in the list `list`. */
function matchOf(list: Node[], name: string): string {
  const found = list.filter((node) => node.name === name);
  if (found.length !== 1) throw new Error(`${found.length} patterns named ${name}`);
  return found[0]!.match!;
}

/** The words between `prefix` and `suffix` in `regex`, without the branches in `drop`, sorted. */
function words(regex: string, prefix: string, suffix: string, drop: string[] = []): string[] {
  if (!regex.startsWith(prefix) || !regex.endsWith(suffix)) throw new Error(`${prefix} … ${suffix} is not ${regex.slice(0, 60)}`);
  let body = regex.slice(prefix.length, regex.length - suffix.length);
  for (const branch of drop) {
    if (!body.includes(`|${branch}`)) throw new Error(`no branch ${branch}`);
    body = body.replace(`|${branch}`, "");
  }
  const list = [...new Set(expand(body))].sort();
  if (list.some((word) => !/^\w+$/.test(word))) throw new Error(`a word that is not \\w+ in ${prefix}`);
  return list;
}

const root = grammar.patterns;
const methods = grammar.repository["method_names"]!.patterns!;
const functions = grammar.repository["function_names"]!.patterns!;

const lists: [string, string, string[]][] = [
  [
    "KEYWORD_CONTROL",
    "The words of `keyword.control`.",
    words(matchOf(root, "keyword.control.coffee"), "\\b(?<![$.])(", ")(?!\\s*:)\\b", ["(?<=for)\\s+own"]),
  ],
  ["RESERVED", "The words of `keyword.reserved`.", words(matchOf(root, "keyword.reserved.coffee"), "\\b(?<![$.])(", ")(?!\\s*:)\\b")],
  ["SUPPORT_CLASSES", "The words of `support.class`.", words(matchOf(root, "support.class.coffee"), "\\b(", ")\\b")],
  [
    "CONSOLE_METHODS",
    "The words of `support.function.console`.",
    words(matchOf(root, "support.function.console.coffee"), "((?<=console\\.)(", "))\\b"),
  ],
  [
    "ARRAY_METHODS",
    "The words of `support.function.method.array`.",
    words(matchOf(root, "support.function.method.array.coffee"), "((?<=\\.)(", "))\\b"),
  ],
  [
    "OBJECT_STATICS",
    "The words of `support.function.static.object`.",
    words(matchOf(root, "support.function.static.object.coffee"), "((?<=Object\\.)(", "))\\b"),
  ],
  [
    "MATH_STATICS",
    "The words of `support.function.static.math`.",
    words(matchOf(root, "support.function.static.math.coffee"), "((?<=Math\\.)(", "))\\b"),
  ],
  [
    "NUMBER_STATICS",
    "The words of `support.function.static.number`.",
    words(matchOf(root, "support.function.static.number.coffee"), "((?<=Number\\.)(", "))\\b"),
  ],
  [
    "EVENT_HANDLERS",
    "The words of `support.function.event-handler`, with their `on`.",
    words(matchOf(methods, "support.function.event-handler.coffee"), "\\bon(", ")\\b").map((word) => `on${word}`).sort(),
  ],
  [
    "SUPPORT_METHODS",
    "The words of the methods' `support.function`, without `plugins.refresh`.",
    words(matchOf(methods, "support.function.coffee"), "\\b(", ")\\b", ["plugins.refresh"]),
  ],
  ["DOM_METHODS", "The words of `support.function.dom`.", words(matchOf(methods, "support.function.dom.coffee"), "\\b(", ")\\b")],
  [
    "SUPPORT_FUNCTIONS",
    "The words of the functions' `support.function`.",
    words(matchOf(functions, "support.function.coffee"), "\\b(", ")\\b"),
  ],
];

const header = dedent`
  //! The words the grammar's alternations spell out, sorted. Generated by
  //! \`oracle/coffee-words.ts\`; do not edit.`;
const tables = lists.map(([name, doc, list]) => dedent`
  /// ${doc}
  pub(super) const ${name}: &[&[u8]] = &[
      ${list.map((word) => `b"${word}",`).join("\n")}
  ];`);
await writeRust(new URL("../src/coffee/words.rs", import.meta.url).pathname, `${[header, ...tables].join("\n\n")}\n`);
console.log(lists.map(([name, , list]) => `${name} ${list.length}`).join(", "));
